                      "description": "场景编号（章内序号）"
                    },
                    "scene_location": {
                      "type": "string",
                      "description": "场景地点（具体环境）"
                    },
                    "characters_present": {
                      "type": "array",
                      "description": "在场角色",
                      "items": {
                        "type": "string"
                      },
                      "minItems": 1
                    },
                    "scene_purpose": {
                      "type": "string",
                      "description": "本场景在chapter_synopsis中的作用"
                    },
                    "core_action": {
                      "type": "string",
                      "description": "核心动作（谁对谁做了什么，必须是可视化的具体行为，不能是抽象表述）"
                    },
                    "conflict_point": {
                      "type": "string",
                      "description": "本场景的冲突爆发点"
                    },
                    "emotional_shift": {
                      "type": "string",
